head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > E > oneditfull]<br/>입력값의 길이가 maxByteLength 값에 도달할때 발생합니다.",
    "validation" : [
        "입력값의 길이가 maxByteLength 값에 도달할때 이벤트가 발생합니다.",
        "입력값이 maxByteLength 값에 도달할때 마지막 문자가 한글인 경우는 이벤트가 발생하지 않습니다.",
        "입력값이 maxByteLength 값에 도달한 후 추가 입력하는 경우도 이벤트가 발생합니다.",
        "maxByteLength 값보다 긴 길이의 입력값을 붙여넣기하면 이벤트가 두번 발생합니다.",
        "입력값을 붙여넣기 할때 maxByteLength 값에 걸리는 문자가 한글인 경우 이벤트가 발생하지 않습니다.",        
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
      // 기존 target 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // 조건 설정 (startcomp)   
    let properties = {
        maxByteLength : wf_sample.getObj("con_maxByteLength").getValue(),
        style: "width:200px; height:30px;"             
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oneditfull"]);  

    $c.gcm.createEmptyInput(cList, eList);
}
